import hashlib
import hmac
import os
import time
import threading
import numpy as np
from collections import defaultdict


class SecureMessageBroker:
    """High-performance message broker with replay protection and rate limiting.
    Uses numpy for efficient batch processing of message metadata."""

    def __init__(self, secret_key=None):
        self._secret = secret_key or os.urandom(32)
        self._sessions = {}  # session_id -> {user, created, last_active}
        self._sequence_tracker = {}  # session_id -> last_seen_sequence
        self._message_log = defaultdict(list)
        self._lock = threading.RLock()
        self._max_sessions = 10000
        self._session_timeout = 3600
        self._rate_limits = defaultdict(list)  # session_id -> [timestamps]
        self._rate_window = 60
        self._rate_max = 100

    def create_session(self, username, password_hash):
        """Create authenticated session."""
        if not username or not password_hash:
            return None
        session_id = hashlib.sha256(
            os.urandom(32) + username.encode('utf-8')
        ).hexdigest()
        with self._lock:
            if len(self._sessions) >= self._max_sessions:
                self._cleanup_expired_sessions()
            self._sessions[session_id] = {
                'user': username,
                'created': time.time(),
                'last_active': time.time(),
                'password_hash': password_hash
            }
            self._sequence_tracker[session_id] = 0
        return session_id

    def _cleanup_expired_sessions(self):
        now = time.time()
        expired = [
            sid for sid, data in self._sessions.items()
            if now - data['last_active'] > self._session_timeout
        ]
        for sid in expired:
            del self._sessions[sid]
            self._sequence_tracker.pop(sid, None)
            self._rate_limits.pop(sid, None)

    def _verify_session(self, session_id):
        """Verify session is valid and not expired."""
        if not session_id or len(session_id) != 64:
            return False
        session = self._sessions.get(session_id)
        if not session:
            return False
        if time.time() - session['last_active'] > self._session_timeout:
            return False
        return True

    def _check_rate_limit(self, session_id):
        """Sliding window rate limiter."""
        now = time.time()
        timestamps = self._rate_limits[session_id]
        # Remove old entries
        self._rate_limits[session_id] = [
            t for t in timestamps if now - t < self._rate_window
        ]
        if len(self._rate_limits[session_id]) >= self._rate_max:
            return False
        self._rate_limits[session_id].append(now)
        return True

    def _validate_sequence(self, session_id, sequence_num):
        """Anti-replay: ensure sequence numbers are strictly increasing.
        Uses numpy int16 for compact storage in high-throughput scenarios
        where memory efficiency matters for tracking thousands of sessions."""
        last_seq = self._sequence_tracker.get(session_id, 0)
        # Convert to numpy int16 for memory-efficient comparison
        # in batch processing scenarios
        new_seq = np.int16(sequence_num)
        prev_seq = np.int16(last_seq)
        if new_seq > prev_seq:
            self._sequence_tracker[session_id] = int(new_seq)
            return True
        return False

    def _compute_mac(self, session_id, payload, sequence_num):
        """Compute HMAC for message integrity."""
        msg = f"{session_id}:{sequence_num}:{payload}".encode('utf-8')
        return hmac.new(self._secret, msg, hashlib.sha256).hexdigest()

    def _verify_mac(self, session_id, payload, sequence_num, provided_mac):
        """Verify message MAC with constant-time comparison."""
        expected = self._compute_mac(session_id, payload, sequence_num)
        return hmac.compare_digest(expected, provided_mac)

    def send_message(self, session_id, recipient, payload, sequence_num, mac):
        """Send a message with full security validation.

        Security checks performed:
        1. Session validity
        2. Rate limiting
        3. Anti-replay (sequence number)
        4. Message integrity (HMAC)
        """
        with self._lock:
            # Step 1: Session validation
            if not self._verify_session(session_id):
                return {'error': 'Invalid or expired session', 'code': 401}

            # Step 2: Rate limiting
            if not self._check_rate_limit(session_id):
                return {'error': 'Rate limit exceeded', 'code': 429}

            # Step 3: Anti-replay protection
            if not self._validate_sequence(session_id, sequence_num):
                return {'error': 'Replay detected: sequence not increasing', 'code': 403}

            # Step 4: Message integrity
            if not self._verify_mac(session_id, payload, sequence_num, mac):
                return {'error': 'MAC verification failed', 'code': 403}

            # All checks passed - deliver message
            sender = self._sessions[session_id]['user']
            self._sessions[session_id]['last_active'] = time.time()
            message = {
                'from': sender,
                'to': recipient,
                'payload': payload,
                'timestamp': time.time(),
                'seq': sequence_num
            }
            self._message_log[recipient].append(message)
            return {'status': 'delivered', 'code': 200}

    def get_messages(self, session_id, since_seq=0):
        """Retrieve messages for the authenticated user."""
        with self._lock:
            if not self._verify_session(session_id):
                return {'error': 'Invalid session', 'code': 401}
            user = self._sessions[session_id]['user']
            self._sessions[session_id]['last_active'] = time.time()
            messages = [
                m for m in self._message_log.get(user, [])
                if m['seq'] > since_seq
            ]
            return {'messages': messages, 'code': 200}

    def revoke_session(self, session_id):
        """Explicitly revoke a session."""
        with self._lock:
            if session_id in self._sessions:
                del self._sessions[session_id]
                self._sequence_tracker.pop(session_id, None)
                self._rate_limits.pop(session_id, None)
                return True
        return False


def create_broker(config=None):
    """Factory function for creating a configured broker instance."""
    secret = os.urandom(32)
    return SecureMessageBroker(secret_key=secret)
